C[1] = C[0] + (1/sqrt(3))*(rotate(90)*(B[0] - A[0]));

draw(A[0]--B[0]--C[0]--cycle);
draw(A[1]--D);
draw(B[1]--E);
draw(C[1]--F);

label("$A$", A[0], NW);
dot("$A'$", A[1], N);
label("$B$", B[0], S);
dot("$B'$", B[1], SW);
label("$C$", C[0], S);
dot("$C'$", C[1], SE);
[/asy]

